import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { LibraryListingDto } from "@printrio/shared";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { FakeMoonraker } from "../dev/fake-moonraker.ts";
import { createTestApp, sessionCookie } from "./helpers.ts";

let ctx: Awaited<ReturnType<typeof createTestApp>>;
let admin: string;
let operator: string;
let fake: FakeMoonraker;

const PNG =
  "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";
const ORCA = [
  "; generated by OrcaSlicer 2.1.1 on 2026-10-20 at 10:00:00 UTC",
  `; thumbnail begin 300x300 ${PNG.length}`,
  `; ${PNG}`,
  "; thumbnail end",
  "G28",
  "G1 X10 Y10",
  "; filament used [mm] = 1520.4",
  "; filament used [g] = 4.53",
  "; estimated printing time (normal mode) = 42m 10s",
  "; layer_height = 0.2",
  "; filament_type = PETG",
].join("\n");

const api = (method: "GET" | "POST" | "DELETE", url: string, payload?: object, cookie = admin) =>
  ctx.app.inject({ method, url, payload, headers: { cookie } });
const upload = (name: string, content: string, dir = "", cookie = admin) => {
  const boundary = "----printrio";
  return ctx.app.inject({
    method: "POST",
    url: `/api/library${dir ? `?dir=${encodeURIComponent(dir)}` : ""}`,
    headers: { cookie, "content-type": `multipart/form-data; boundary=${boundary}` },
    payload: `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${name}"\r\nContent-Type: application/octet-stream\r\n\r\n${content}\r\n--${boundary}--\r\n`,
  });
};
const listing = async (dir = ""): Promise<LibraryListingDto> =>
  (await api("GET", `/api/library${dir ? `?dir=${encodeURIComponent(dir)}` : ""}`)).json();

beforeAll(async () => {
  ctx = await createTestApp();
  const setup = await ctx.app.inject({
    method: "POST",
    url: "/api/setup",
    payload: {
      email: "admin@example.com",
      displayName: "Admin",
      password: "correct horse battery",
    },
  });
  admin = sessionCookie(setup.headers["set-cookie"]);
  await api("POST", "/api/users", {
    email: "op@example.com",
    displayName: "Operator",
    password: "operator password",
    role: "operator",
  });
  const login = await ctx.app.inject({
    method: "POST",
    url: "/api/auth/login",
    payload: { email: "op@example.com", password: "operator password" },
  });
  operator = sessionCookie(login.headers["set-cookie"]);
  fake = new FakeMoonraker({ tickMs: 0 });
  await fake.start();
});

afterAll(async () => {
  await ctx.close();
  await fake.stop();
});

describe("G-code library", () => {
  it("stores uploads with slicer metadata and a thumbnail", async () => {
    const res = await upload("bracket.gcode", ORCA, "", operator);
    expect(res.statusCode).toBe(201);
    expect(res.json()).toMatchObject({
      path: "bracket.gcode",
      slicer: "OrcaSlicer 2.1.1",
      estimatedSeconds: 2530,
      filamentGrams: 4.53,
      material: "PETG",
      hasThumbnail: true,
      uploadedBy: "Operator",
    });
    const thumb = await api("GET", "/api/library/thumbnail?path=bracket.gcode");
    expect(thumb.headers["content-type"]).toBe("image/png");
    const download = await api("GET", "/api/library/download?path=bracket.gcode");
    expect(download.body).toBe(ORCA);
    expect(download.headers["content-disposition"]).toBe('attachment; filename="bracket.gcode"');
  });

  it("organises files in folders and picks up files copied into the volume", async () => {
    expect(
      (await api("POST", "/api/library/folders", { path: "Customers/Novak" })).statusCode,
    ).toBe(201);
    await upload("plate.gcode", "G28\n", "Customers/Novak");
    mkdirSync(join(ctx.dataDir, "files", "Manual"), { recursive: true });
    writeFileSync(
      join(ctx.dataDir, "files", "Manual", "copied.gcode"),
      "; generated by PrusaSlicer 2.8.0\nG28\n",
    );
    writeFileSync(join(ctx.dataDir, "files", "notes.txt"), "not g-code");

    const root = await listing();
    expect(root.directories).toEqual(["Customers", "Manual"]);
    expect(root.files.map((f) => f.name)).toEqual(["bracket.gcode"]);
    expect((await listing("Customers/Novak")).files.map((f) => f.path)).toEqual([
      "Customers/Novak/plate.gcode",
    ]);
    const manual = await listing("Manual");
    expect(manual.files[0]).toMatchObject({
      name: "copied.gcode",
      slicer: "PrusaSlicer 2.8.0",
      uploadedBy: null,
    });
  });

  it("rejects bad paths and non-G-code files", async () => {
    expect((await api("GET", "/api/library?dir=../etc")).statusCode).toBe(400);
    expect((await api("GET", "/api/library?dir=missing")).statusCode).toBe(400);
    expect((await api("GET", "/api/library/download?path=../../secret")).statusCode).toBe(400);
    expect((await upload("evil.sh", "rm -rf /")).statusCode).toBe(400);
    expect((await api("GET", "/api/library/download?path=missing.gcode")).statusCode).toBe(404);
  });

  it("sends files to a printer and can start the print", async () => {
    const printerId = (await api("POST", "/api/printers", { name: "Lib", url: fake.url })).json()
      .id;
    for (let i = 0; i < 100; i++) {
      const state = (await api("GET", "/api/printers")).json().printers[0].status.state;
      if (state === "idle") break;
      await new Promise((r) => setTimeout(r, 20));
    }
    const sent = await api("POST", "/api/library/send", {
      path: "Customers/Novak/plate.gcode",
      printerId,
    });
    expect(sent.json()).toEqual({ path: "plate.gcode", printing: false });
    expect(fake.uploads).toContain("plate.gcode");

    const printed = await api("POST", "/api/library/send", {
      path: "bracket.gcode",
      printerId,
      print: true,
    });
    expect(printed.json()).toEqual({ path: "bracket.gcode", printing: true });
    for (let i = 0; i < 100; i++) {
      const state = (await api("GET", "/api/printers")).json().printers[0].status.state;
      if (state === "printing") break;
      await new Promise((r) => setTimeout(r, 20));
    }
    const busy = await api("POST", "/api/library/send", {
      path: "bracket.gcode",
      printerId,
      print: true,
    });
    expect(busy.statusCode).toBe(409);
  });

  it("lets admins delete files and empty folders", async () => {
    expect(
      (await api("DELETE", "/api/library?path=bracket.gcode", undefined, operator)).statusCode,
    ).toBe(403);
    expect((await api("DELETE", "/api/library?path=bracket.gcode")).statusCode).toBe(204);
    expect((await api("DELETE", "/api/library?path=Customers/Novak")).statusCode).toBe(400);
    await api("DELETE", "/api/library?path=Customers/Novak/plate.gcode");
    expect((await api("DELETE", "/api/library?path=Customers/Novak")).statusCode).toBe(204);
    expect((await listing("Customers")).directories).toEqual([]);
  });
});
